  "decline_reason": "",
  "claims": [
    {
      "text": "Yes, in principle: the Manual says a section 43 ground for rejection is appropriate where a mark connotes a particular plant variety or other plant name and covers plants or plant materials of the same or a closely related genus.",
      "quotes": [
        {
          "ref": "TMM/Part29/1/1/2",
          "quote": "If a trade mark contains or consists of word/s which connote a particular plant variety or other plant name, and is applied to plants or plant materials of the same or a closely related genus, it is likely to deceive or cause confusion as to the true nature of those plants or plant materials and a ground for rejection under section 43 of the Act will be appropriate."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The statutory test requires rejection if, because of a connotation of the mark or a sign within it, use for the particular goods or services would be likely to deceive or cause confusion.",
      "quotes": [
        {
          "ref": "TMA1995/s43",
          "quote": "An application for the registration of a trade mark in respect of particular goods or services must be rejected if, because of some connotation that the trade mark or a sign contained in the trade mark has, the use of the trade mark in relation to those goods or services would be likely to deceive or cause confusion."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual explains that the connotation must be immediate and that a known variety name may create that connotation, with deception or confusion likely when the mark is used on a different variety of the same or a closely related genus.",
      "quotes": [
        {
          "ref": "TMM/Part32A/2/4/2/4/1",
          "quote": "Section 43 requires that the connotation is immediate."
        },
        {
          "ref": "TMM/Part32A/2/4/2/4/1",
          "quote": "Therefore, if the trade mark contains or consists of a known variety name, the connotation may be immediate, and deception or confusion is likely if the trade mark is used on a different variety of the same or a closely related genus."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The examiner must nevertheless consider the variety name within the mark as a whole: a dictionary word appearing in a phrase may not convey an immediate variety connotation.",
      "quotes": [
        {
          "ref": "TMM/Part32A/2/4/2/4/1",
          "quote": "However, the examiner needs to consider how the variety name appears within the trade mark as a whole. For example, if the plant name is a dictionary word appearing in a phrase then connotation may not be immediate."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
